from pathlib import Path

p=Path('clientes.html')
s=p.read_text()
if 'google-sync.js?v=11' not in s:
    s=s.replace('</body>','<script type="module" src="google-sync.js?v=11"></script>\n</body>')
if 'id="dialogModal"' not in s:
    s=s.replace('.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}', '.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.danger-btn{background:#b91c1c;color:#fff}')
    marker='<div id="toast" class="toast"></div>'
    dialog='''<div id="dialogModal" class="modal"><div class="sheet"><h3 id="dialogTitle"></h3><p id="dialogText"></p><div id="dialogFields"></div><div class="sheet-actions"><button class="secondary" onclick="finishDialog(false)">Cancelar</button><button id="dialogConfirm" class="primary" onclick="finishDialog(true)">Confirmar</button></div></div></div>\n'''
    s=s.replace(marker,dialog+marker)
old="""async function boot(){try{db=await openDB();const saved=await dbGet();if(saved&&Array.isArray(saved.clients)&&Array.isArray(saved.events)){state=saved}else{let old=null;try{old=JSON.parse(localStorage.getItem('cdv_clientes_v1')||localStorage.getItem(KEY)||'null')}catch(_){}if(old&&Array.isArray(old.clients)&&Array.isArray(old.events)){state=old;await dbPut(state)}else{state={clients:[],events:[]};await dbPut(state)}localStorage.setItem(KEY,JSON.stringify(state))}if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});setStatus('Dados salvos neste aparelho','ok')}catch(e){try{const old=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('cdv_clientes_v1')||'null');if(old&&Array.isArray(old.clients)&&Array.isArray(old.events))state=old}catch(_){}setStatus('Modo de segurança: armazenamento local','warn')}render()}"""
new="""async function boot(){try{db=await openDB();let local=null;try{local=JSON.parse(localStorage.getItem(KEY)||'null')}catch(_){}const saved=await dbGet();if(local&&Array.isArray(local.clients)&&Array.isArray(local.events)){state=local;if(JSON.stringify(saved?.data||null)!==JSON.stringify(state))await dbPut(state)}else if(saved&&Array.isArray(saved.clients)&&Array.isArray(saved.events)){state=saved;localStorage.setItem(KEY,JSON.stringify(state))}else{state={clients:[],events:[]};await dbPut(state);localStorage.setItem(KEY,JSON.stringify(state))}if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});setStatus('Dados salvos neste aparelho','ok')}catch(e){try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old&&Array.isArray(old.clients)&&Array.isArray(old.events))state=old}catch(_){}setStatus('Modo de segurança: armazenamento local','warn')}render()}"""
if old not in s: raise SystemExit('boot pattern not found')
s=s.replace(old,new)
if 'window.__applySyncedState' not in s:
    s=s.replace('function client(id){return state.clients.find(c=>String(c.id)===String(id))}', "window.__applySyncedState=function(next){state={clients:Array.isArray(next?.clients)?next.clients:[],events:Array.isArray(next?.events)?next.events:[]};try{localStorage.setItem(KEY,JSON.stringify(state))}catch(_){}render();setStatus('Atualização recebida de outro aparelho.','ok')};\nfunction client(id){return state.clients.find(c=>String(c.id)===String(id))}")
start=s.index('async function renew(id){')
end=s.index('function render(){',start)
replacement='''function showDialog({title,text,fields=[],confirm='Confirmar',danger=false}){byId('dialogTitle').textContent=title;byId('dialogText').textContent=text;byId('dialogConfirm').textContent=confirm;byId('dialogConfirm').className='primary'+(danger?' danger-btn':'');byId('dialogFields').innerHTML=fields.map(f=>`<div style="margin-top:9px"><label>${esc(f.label)}</label><input id="${escAttr(f.id)}" type="${f.type||'text'}" value="${escAttr(f.value??'')}" ${f.inputmode?`inputmode="${escAttr(f.inputmode)}"`:''} ${f.step?`step="${escAttr(f.step)}"`:''}></div>`).join('');byId('dialogModal').classList.add('open');setTimeout(()=>{const first=byId('dialogFields').querySelector('input');if(first)first.focus()},60);return new Promise(resolve=>{dialogResolve=resolve})}
function finishDialog(ok){const result={ok,values:{}};if(ok)byId('dialogFields').querySelectorAll('input').forEach(i=>result.values[i.id]=i.value);byId('dialogModal').classList.remove('open');const r=dialogResolve;dialogResolve=null;if(r)r(result)}
async function renew(id){const c=client(id);if(!c)return;const r=await showDialog({title:'Renovar crédito',text:`Quantas marmitas ${c.name} renovou?`,fields:[{id:'renewQty',label:'Quantidade',type:'number',value:22,step:1,inputmode:'numeric'}],confirm:'Renovar'});if(!r.ok)return;const n=Math.max(1,Math.floor(Number(r.values.renewQty)||0));c.credit+=n;state.events.unshift({id:crypto.randomUUID(),clientId:c.id,type:'renew',qty:n,date:today(),note:'Renovação'});await save();showToast(`+${n} marmitas de crédito`)}
async function editClient(id){const c=client(id);if(!c)return;const r=await showDialog({title:'Editar cliente',text:'Altere os dados do cliente.',fields:[{id:'editName',label:'Nome',value:c.name},{id:'editPrice',label:'Preço por marmita (R$)',type:'number',value:c.price,step:'0.01',inputmode:'decimal'}],confirm:'Salvar'});if(!r.ok)return;c.name=r.values.editName.trim()||c.name;c.price=Number(r.values.editPrice)||c.price;await save();showToast('Cliente atualizado')}
async function removeClient(id){const c=client(id);if(!c)return;const r=await showDialog({title:'Excluir cliente',text:`Excluir ${c.name}? O histórico dele também será removido.`,confirm:'Excluir',danger:true});if(!r.ok)return;state.clients=state.clients.filter(x=>String(x.id)!==String(id));state.events=state.events.filter(x=>String(x.clientId)!==String(id));await save();showToast('Cliente excluído')}
'''
s=s[:start]+replacement+s[end:]
s=s.replace("localStorage.setItem(KEY,JSON.stringify(state));setStatus('Dados salvos neste aparelho','ok')", "localStorage.setItem(KEY,JSON.stringify(state));window.dispatchEvent(new CustomEvent('cdv-local-save',{detail:state}));setStatus('Dados salvos neste aparelho','ok')")
s=s.replace("localStorage.setItem(KEY,JSON.stringify(state));setStatus('Salvo no armazenamento local','warn')", "localStorage.setItem(KEY,JSON.stringify(state));window.dispatchEvent(new CustomEvent('cdv-local-save',{detail:state}));setStatus('Salvo no armazenamento local','warn')")
p.write_text(s)

g=Path('google-sync.js')
gs=g.read_text()
gs=gs.replace("const LOCAL='cdv_clientes_v2',DB_NAME='cdv_clientes_db',STORE='state',CONNECTED='cdv_google_connected';", "const LOCAL='cdv_clientes_v2',DB_NAME='cdv_clientes_db',STORE='state',CONNECTED='cdv_google_connected',META='cdv_clientes_sync_meta';")
gs=gs.replace("function saveLocal(s){try{localStorage.setItem(LOCAL,JSON.stringify(s));lastLocal=JSON.stringify(s)}catch(_){};return idbPut(s)}", "function readMeta(){try{return JSON.parse(localStorage.getItem(META)||'{}')}catch(_){return {}}}\nfunction writeMeta(updatedAt){try{localStorage.setItem(META,JSON.stringify({updatedAt:Number(updatedAt)||Date.now()}))}catch(_){} }\nfunction saveLocal(s,updatedAt=Date.now()){try{localStorage.setItem(LOCAL,JSON.stringify(s));lastLocal=JSON.stringify(s);writeMeta(updatedAt)}catch(_){};return idbPut(s)}")
gs=gs.replace("async function push(u,s){if(!u||writingRemote)return;const payload={state:s,updatedAt:Date.now(),email:u.email||null};await setDoc(doc(db,'clientes',u.uid),payload,{merge:true});lastLocal=JSON.stringify(s);setStatus('Sincronizado com o Google.')}", "async function push(u,s,updatedAt=Date.now()){if(!u||writingRemote)return;const stamp=Number(updatedAt)||Date.now();const payload={state:s,updatedAt:stamp,email:u.email||null};await setDoc(doc(db,'clientes',u.uid),payload,{merge:true});lastLocal=JSON.stringify(s);writeMeta(stamp);setStatus('Sincronização ativa. Última alteração enviada.')}")
gs=gs.replace("async function pull(u){const ref=doc(db,'clientes',u.uid),snap=await getDoc(ref);const local=localState();if(!snap.exists()){if(hasData(local))await push(u,local);return local}const remote=snap.data().state||{clients:[],events:[]};const remoteJson=JSON.stringify(remote),localJson=JSON.stringify(local);if(remoteJson===localJson){lastLocal=localJson;return local}if(hasData(remote)||!hasData(local)){writingRemote=true;await saveLocal(remote);writingRemote=false;setStatus('Dados sincronizados do outro aparelho.');return remote}await push(u,local);return local}", "async function pull(u){const ref=doc(db,'clientes',u.uid),snap=await getDoc(ref),local=localState(),meta=readMeta(),localUpdated=Number(meta.updatedAt)||0;if(!snap.exists()){if(hasData(local))await push(u,local,localUpdated||Date.now());return local}const remote=snap.data().state||{clients:[],events:[]},remoteUpdated=Number(snap.data().updatedAt)||0,remoteJson=JSON.stringify(remote),localJson=JSON.stringify(local);if(remoteUpdated>localUpdated){writingRemote=true;await saveLocal(remote,remoteUpdated);writingRemote=false;window.__applySyncedState?.(remote);setStatus('Dados sincronizados do outro aparelho.');return remote}if(localUpdated>remoteUpdated){await push(u,local,localUpdated);return local}if(remoteJson!==localJson){if(hasData(remote)){writingRemote=true;await saveLocal(remote,remoteUpdated||Date.now());writingRemote=false;window.__applySyncedState?.(remote);return remote}if(hasData(local)){await push(u,local,localUpdated||Date.now());return local}}lastLocal=localJson;return local}")
gs=gs.replace("function watch(u){if(watchStarted)return;watchStarted=true;onSnapshot(doc(db,'clientes',u.uid),async snap=>{if(!snap.exists()||writingRemote)return;const remote=snap.data().state;if(!remote)return;const local=localState(),r=JSON.stringify(remote);if(r===JSON.stringify(local))return;writingRemote=true;await saveLocal(remote);writingRemote=false;setStatus('Atualização recebida de outro aparelho.')})}", "function watch(u){if(watchStarted)return;watchStarted=true;onSnapshot(doc(db,'clientes',u.uid),async snap=>{if(!snap.exists()||writingRemote)return;const remote=snap.data().state;if(!remote)return;const remoteUpdated=Number(snap.data().updatedAt)||0,local=localState(),localUpdated=Number(readMeta().updatedAt)||0;if(remoteUpdated<=localUpdated)return;if(JSON.stringify(remote)===JSON.stringify(local)){writeMeta(remoteUpdated);lastLocal=JSON.stringify(local);return}writingRemote=true;await saveLocal(remote,remoteUpdated);writingRemote=false;window.__applySyncedState?.(remote);setStatus('Atualização recebida de outro aparelho.')})}")
gs=gs.replace("const s=localState(),j=JSON.stringify(s);if(j!==lastLocal&&auth.currentUser){lastLocal=j;try{await push(auth.currentUser,s)}catch(e){setStatus('Aguardando conexão para sincronizar.')}}", "const s=localState(),j=JSON.stringify(s);if(j!==lastLocal&&auth.currentUser){const stamp=Date.now();lastLocal=j;writeMeta(stamp);try{await push(auth.currentUser,s,stamp)}catch(e){setStatus('Aguardando conexão para sincronizar.')}}")
g.write_text(gs)
